package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import java.util.List;import com.mojang.blaze3d.vertex.*;import org.lwjgl.system.MemoryUtil;import team.creative.littletiles.client.render.mc.MeshDataExtender;import team.creative.littletiles.client.render.overlay.PreviewRenderer;import team.creative.littletiles.common.math.box.collection.LittleBoxes;
public class DirectPolygonMesh {
 public static MeshData write(ByteBufferBuilder owner,List<int[]> faces,double scale){if(faces.isEmpty())return null;long ptr=owner.reserve(Math.multiplyExact(faces.size(),64));for(var f:faces){int n=f[0],a=f[3],b=f[4];boolean forward=((a+1)%3==b)==(f[1]==1);for(int j=0;j<4;j++){int c=forward?j:(4-j)%4;float normal=(float)(f[2]*scale),u=(float)(f[c==1||c==2?6:5]*scale),v=(float)(f[c>=2?8:7]*scale);MemoryUtil.memPutFloat(ptr,n==0?normal:a==0?u:v);MemoryUtil.memPutFloat(ptr+4,n==1?normal:a==1?u:v);MemoryUtil.memPutFloat(ptr+8,n==2?normal:a==2?u:v);MemoryUtil.memPutInt(ptr+12,-1);ptr+=16;}}int count=faces.size()*4;var mesh=new MeshData(owner.build(),new MeshData.DrawState(DefaultVertexFormat.POSITION_COLOR,count,faces.size()*6,VertexFormat.Mode.QUADS,VertexFormat.IndexType.least(count)));((MeshDataExtender)(Object)mesh).keepAlive(true);return mesh;}
 public static PreviewRenderer.BoxRenderResult surface(PreviewRenderer renderer,LittleBoxes boxes,List<int[]> faces){var owner=renderer.createBuffer();try{return new PreviewRenderer.BoxRenderResult(boxes,boxes.pos,owner,write(owner,faces,boxes.grid.pixelLength));}catch(Throwable t){owner.close();throw t;}}
}
